std::vector<int> two_sum(const std::vector<int>& nums, int target) {
    std::unordered_map<int, int> seen;
    for (int i = 0; i < (int)nums.size(); i++) {
        int need = target - nums[i];
        if (seen.count(need)) return {seen[need], i};
        seen[nums[i]] = i;
    } return {}; }

bool is_valid(const std::string& s) { std::stack<char> stack;
    for (char c : s) { if (c == '(' || c == '[' || c == '{') { stack.push(c); } else { if (stack.empty()) return false;
            char top = stack.top(); stack.pop();
            if (c == ')' && top != '(') return false;
            if (c == ']' && top != '[') return false;
            if (c == '}' && top != '{') return false; } }
    return stack.empty(); }

struct ListNode { int val;
    ListNode *next;
    ListNode(int x) : val(x), next(nullptr) {} }; ListNode* reverse_list(ListNode* head) { ListNode* prev = nullptr;
    while (head) { ListNode* next = head->next;
        head->next = prev;
        prev = head;
        head = next; } return prev; }

int max_sub_array(const std::vector<int>& nums) {
    int best = nums[0], cur = nums[0];
    for (int i = 1; i < (int)nums.size(); i++) {
        cur = std::max(nums[i], cur + nums[i]);
        best = std::max(best, cur);
    } return best;
}

struct ListNode { int val; ListNode *next;
    ListNode(int x) : val(x), next(nullptr) {} }; ListNode* merge_two_lists(ListNode* a, ListNode* b) { ListNode dummy(0);
    ListNode* tail = &dummy;
    while (a && b) { if (a->val <= b->val) { tail->next = a;
            a = a->next; } else { tail->next = b;
            b = b->next; } tail = tail->next; } tail->next = a ? a : b;
    return dummy.next; }

int max_profit(const std::vector<int>& prices) {
    int best = 0, low = prices[0];
    for (int price : prices) {
        best = std::max(best, price - low);
        low = std::min(low, price);
    } return best;
}

bool is_palindrome(const std::string& s) {
    int left = 0, right = (int)s.size() - 1;
    while (left < right) { while (left < right && !std::isalnum(s[left])) left++;
        while (left < right && !std::isalnum(s[right])) right--;
        if (std::tolower(s[left]) != std::tolower(s[right])) return false;
        left++;
        right--; } return true; }

int climb_stairs(int n) { int a = 1, b = 1;
    for (int i = 0; i < n - 1; i++) {
        int temp = a + b;
        a = b;
        b = temp;
    } return b;
}

int binary_search(const std::vector<int>& arr, int target) {
    int lo = 0, hi = (int)arr.size() - 1;
    while (lo <= hi) { int mid = lo + (hi - lo) / 2;
        if (arr[mid] == target) return mid;
        if (arr[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    } return -1; }

int single_number(const std::vector<int>& nums) {
    int result = 0;
    for (int n : nums) result ^= n;
    return result;
}

bool contains_duplicate(const std::vector<int>& nums) {
    std::unordered_set<int> seen;
    for (int n : nums) {
        if (!seen.insert(n).second) return true;
    }
    return false;
}

int majority_element(const std::vector<int>& nums) {
    int count = 0, candidate = 0;
    for (int n : nums) {
        if (count == 0) candidate = n;
        count += (n == candidate) ? 1 : -1;
    } return candidate;
}

void move_zeroes(std::vector<int>& nums) {
    int write = 0;
    for (int n : nums) {
        if (n != 0) nums[write++] = n;
    }
    while (write < (int)nums.size()) nums[write++] = 0;
}

std::vector<int> product_except_self(const std::vector<int>& nums) {
    int n = nums.size();
    std::vector<int> res(n, 1);
    for (int i = 1; i < n; i++) res[i] = res[i - 1] * nums[i - 1];
    int right = 1;
    for (int i = n - 1; i >= 0; i--) { res[i] *= right;
        right *= nums[i]; } return res; }

std::vector<std::vector<int>> merge_intervals(std::vector<std::vector<int>> intervals) {
    std::sort(intervals.begin(), intervals.end());
    std::vector<std::vector<int>> merged;
    for (auto& interval : intervals) { if (merged.empty() || merged.back()[1] < interval[0]) { merged.push_back(interval);
        } else { merged.back()[1] = std::max(merged.back()[1], interval[1]);
        } }
    return merged; }

std::vector<std::vector<std::string>> group_anagrams(const std::vector<std::string>& strs) {
    std::unordered_map<std::string, std::vector<std::string>> groups;
    for (const auto& s : strs) { std::string key = s;
        std::sort(key.begin(), key.end());
        groups[key].push_back(s); } std::vector<std::vector<std::string>> result;
    for (auto& entry : groups) result.push_back(entry.second);
    return result; }

std::string longest_common_prefix(const std::vector<std::string>& strs) {
    std::string prefix = strs[0];
    for (const auto& s : strs) {
        while (s.rfind(prefix, 0) != 0) { prefix.pop_back();
            if (prefix.empty()) return "";
        } }
    return prefix; }

int roman_to_int(const std::string& s) { std::unordered_map<char, int> values = {
        {'I', 1}, {'V', 5}, {'X', 10}, {'L', 50},
        {'C', 100}, {'D', 500}, {'M', 1000} }; int total = 0;
    for (int i = 0; i < (int)s.size(); i++) {
        if (i + 1 < (int)s.size() && values[s[i]] < values[s[i + 1]]) { total -= values[s[i]];
        } else { total += values[s[i]]; } }
    return total; }

bool is_palindrome_number(int x) {
    if (x < 0 || (x % 10 == 0 && x != 0)) return false;
    int reversed = 0;
    while (x > reversed) { reversed = reversed * 10 + x % 10;
        x /= 10;
    } return x == reversed || x == reversed / 10;
}

std::vector<int> plus_one(std::vector<int> digits) {
    for (int i = (int)digits.size() - 1; i >= 0; i--) {
        if (digits[i] < 9) { digits[i]++;
            return digits;
        } digits[i] = 0;
    } digits.insert(digits.begin(), 1);
    return digits; }

int remove_duplicates(std::vector<int>& nums) {
    int write = 0;
    for (int n : nums) {
        if (write == 0 || n != nums[write - 1]) nums[write++] = n;
    }
    return write;
}

void rotate_array(std::vector<int>& nums, int k) {
    int n = nums.size();
    k %= n;
    std::reverse(nums.begin(), nums.end());
    std::reverse(nums.begin(), nums.begin() + k);
    std::reverse(nums.begin() + k, nums.end());
}

int missing_number(const std::vector<int>& nums) {
    int n = nums.size();
    int total = n * (n + 1) / 2;
    for (int num : nums) total -= num;
    return total;
}

std::vector<std::string> fizz_buzz(int n) { std::vector<std::string> result;
    for (int i = 1; i <= n; i++) {
        if (i % 15 == 0) result.push_back("FizzBuzz");
        else if (i % 3 == 0) result.push_back("Fizz");
        else if (i % 5 == 0) result.push_back("Buzz");
        else result.push_back(std::to_string(i));
    } return result; }

bool is_power_of_two(int n) {
    return n > 0 && (n & (n - 1)) == 0;
}

int hamming_weight(unsigned int n) {
    int count = 0;
    while (n) {
        count += n & 1;
        n >>= 1;
    } return count;
}

void reverse_string(std::string& s) {
    int left = 0, right = (int)s.size() - 1;
    while (left < right) std::swap(s[left++], s[right--]);
}

int reverse_integer(int x) {
    long long result = 0;
    while (x != 0) { result = result * 10 + x % 10;
        x /= 10;
    } if (result < INT_MIN || result > INT_MAX) return 0;
    return (int)result;
}

int length_of_last_word(const std::string& s) {
    int i = s.size() - 1, length = 0;
    while (i >= 0 && s[i] == ' ') i--;
    while (i >= 0 && s[i] != ' ') { length++;
        i--;
    } return length;
}

int str_str(const std::string& haystack, const std::string& needle) {
    if (needle.empty()) return 0;
    size_t found = haystack.find(needle);
    return found == std::string::npos ? -1 : (int)found;
}

std::string add_binary(std::string a, std::string b) { std::string result;
    int i = a.size() - 1, j = b.size() - 1, carry = 0;
    while (i >= 0 || j >= 0 || carry) { int total = carry;
        if (i >= 0) total += a[i--] - '0'; if (j >= 0) total += b[j--] - '0';
        result.push_back('0' + total % 2);
        carry = total / 2; } std::reverse(result.begin(), result.end());
    return result; }

int my_sqrt(int x) { if (x < 2) return x;
    int lo = 1, hi = x / 2, answer = 0;
    while (lo <= hi) { int mid = lo + (hi - lo) / 2;
        if ((long long)mid * mid <= x) { answer = mid;
            lo = mid + 1;
        } else { hi = mid - 1; } }
    return answer; }

int title_to_number(const std::string& columnTitle) {
    int result = 0;
    for (char c : columnTitle) {
        result = result * 26 + (c - 'A' + 1);
    }
    return result;
}

bool is_happy(int n) { std::unordered_set<int> seen;
    while (n != 1 && seen.insert(n).second) { int total = 0;
        while (n > 0) { int digit = n % 10;
            total += digit * digit;
            n /= 10;
        } n = total;
    } return n == 1; }

bool is_isomorphic(const std::string& s, const std::string& t) {
    int forward[256] = {0}, backward[256] = {0}; for (int i = 0; i < (int)s.size(); i++) {
        unsigned char a = s[i], b = t[i];
        if (forward[a] == 0) forward[a] = b;
        if (backward[b] == 0) backward[b] = a;
        if (forward[a] != b || backward[b] != a) return false;
    } return true; }

bool word_pattern(const std::string& pattern, const std::string& s) { std::istringstream stream(s);
    std::vector<std::string> words; std::string word; while (stream >> word) words.push_back(word);
    if (pattern.size() != words.size()) return false;
    std::unordered_map<char, std::string> forward; std::unordered_map<std::string, char> backward;
    for (int i = 0; i < (int)words.size(); i++) { char c = pattern[i]; if (forward.count(c) && forward[c] != words[i]) return false;
        if (backward.count(words[i]) && backward[words[i]] != c) return false;
        forward[c] = words[i]; backward[words[i]] = c; } return true; }

std::vector<int> intersection(std::vector<int>& nums1, std::vector<int>& nums2) {
    std::unordered_set<int> set(nums1.begin(), nums1.end());
    std::vector<int> result;
    for (int n : nums2) {
        if (set.erase(n)) result.push_back(n);
    } return result;
}

std::vector<int> sorted_squares(std::vector<int>& nums) { int n = nums.size();
    std::vector<int> result(n);
    int left = 0, right = n - 1;
    for (int i = n - 1; i >= 0; i--) { if (std::abs(nums[left]) > std::abs(nums[right])) { result[i] = nums[left] * nums[left];
            left++; } else { result[i] = nums[right] * nums[right];
            right--; } }
    return result; }

struct TreeNode { int val;
    TreeNode *left, *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
}; int max_depth(TreeNode* root) {
    if (!root) return 0;
    return 1 + std::max(max_depth(root->left), max_depth(root->right));
}

struct TreeNode { int val;
    TreeNode *left, *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
}; bool is_same_tree(TreeNode* p, TreeNode* q) { if (!p && !q) return true;
    if (!p || !q || p->val != q->val) return false;
    return is_same_tree(p->left, q->left) && is_same_tree(p->right, q->right);
}

struct TreeNode { int val;
    TreeNode *left, *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {} }; TreeNode* invert_tree(TreeNode* root) { if (!root) return nullptr;
    std::swap(root->left, root->right);
    invert_tree(root->left);
    invert_tree(root->right);
    return root; }

struct TreeNode { int val;
    TreeNode *left, *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
}; bool mirror(TreeNode* a, TreeNode* b) { if (!a && !b) return true;
    if (!a || !b || a->val != b->val) return false;
    return mirror(a->left, b->right) && mirror(a->right, b->left);
} bool is_symmetric(TreeNode* root) { return !root || mirror(root->left, root->right); }

struct TreeNode { int val; TreeNode *left, *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {} }; int depth(TreeNode* node, int& best) { if (!node) return 0;
    int left = depth(node->left, best);
    int right = depth(node->right, best);
    best = std::max(best, left + right);
    return 1 + std::max(left, right); } int diameter_of_binary_tree(TreeNode* root) { int best = 0;
    depth(root, best); return best; }

struct TreeNode { int val;
    TreeNode *left, *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {} }; int height(TreeNode* node) { if (!node) return 0;
    int left = height(node->left);
    int right = height(node->right);
    if (left < 0 || right < 0 || std::abs(left - right) > 1) return -1;
    return 1 + std::max(left, right); } bool is_balanced(TreeNode* root) { return height(root) >= 0; }

struct TreeNode { int val;
    TreeNode *left, *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
}; bool has_path_sum(TreeNode* root, int targetSum) { if (!root) return false;
    if (!root->left && !root->right) return root->val == targetSum;
    return has_path_sum(root->left, targetSum - root->val)
        || has_path_sum(root->right, targetSum - root->val); }

struct TreeNode { int val;
    TreeNode *left, *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
}; TreeNode* lowest_common_ancestor(TreeNode* root, TreeNode* p, TreeNode* q) {
    while (root) { if (p->val < root->val && q->val < root->val) root = root->left;
        else if (p->val > root->val && q->val > root->val) root = root->right;
        else return root; } return nullptr; }

int search_insert(const std::vector<int>& nums, int target) {
    int lo = 0, hi = nums.size();
    while (lo < hi) { int mid = lo + (hi - lo) / 2;
        if (nums[mid] < target) lo = mid + 1;
        else hi = mid;
    } return lo;
}

std::vector<int> two_sum_sorted(const std::vector<int>& numbers, int target) {
    int left = 0, right = numbers.size() - 1;
    while (left < right) {
        int total = numbers[left] + numbers[right];
        if (total == target) return {left + 1, right + 1}; if (total < target) left++;
        else right--;
    } return {}; }

int length_of_longest_substring(const std::string& s) { std::unordered_map<char, int> last;
    int start = 0, best = 0;
    for (int i = 0; i < (int)s.size(); i++) { char c = s[i];
        if (last.count(c) && last[c] >= start) start = last[c] + 1;
        last[c] = i;
        best = std::max(best, i - start + 1);
    } return best; }

int max_area(const std::vector<int>& height) {
    int left = 0, right = height.size() - 1, best = 0;
    while (left < right) {
        best = std::max(best, std::min(height[left], height[right]) * (right - left));
        if (height[left] < height[right]) left++;
        else right--;
    } return best; }
